import{_ as a,o as t,c as o,a0 as d}from"./chunks/framework.veCcaNqE.js";const p=JSON.parse('{"title":"复杂示例 4：上下文模型索引","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/examples/framework-example4/domain-models.md","filePath":"zh-cn/examples/framework-example4/domain-models.md"}'),n={name:"zh-cn/examples/framework-example4/domain-models.md"};function r(i,e,l,s,m,c){return t(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="复杂示例-4-上下文模型索引" tabindex="-1">复杂示例 4：上下文模型索引 <a class="header-anchor" href="#复杂示例-4-上下文模型索引" aria-label="Permalink to &quot;复杂示例 4：上下文模型索引&quot;">​</a></h1><p><a href="/ospf/examples/framework-example4/domain-models.html">English</a></p><p>Demo4 是架构示例而不是完整的 Kotlin 应用：<code>Application</code> 为空，只有 <code>Demo4GenericQuantitySample</code> 可执行。因此本索引把上下文契约和应用编排分开。 下面的本地模型页是维护性的领域模型文字；数据型和编排型上下文明确记录其不拥有 独立求解变量，而不是虚构一个全局模型。</p><h2 id="_1-上下文图" tabindex="-1">1. 上下文图 <a class="header-anchor" href="#_1-上下文图" aria-label="Permalink to &quot;1. 上下文图&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes material-theme-darker material-theme-lighter vp-code" tabindex="0"><code><span class="line"><span>task + rule + crew + cargo → bunch_generation → bunch_compilation</span></span>
<span class="line"><span>                                      ↘ bunch_selection（分支定价策略）</span></span>
<span class="line"><span>passenger ───────────────────────────→ bunch_compilation（可选管线）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>箭头表示数据和服务依赖，不表示 <code>Application</code> 会在同一个模型中注册所有上下文。</p><h2 id="_2-上下文模型页面" tabindex="-1">2. 上下文模型页面 <a class="header-anchor" href="#_2-上下文模型页面" aria-label="Permalink to &quot;2. 上下文模型页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>上下文</th><th>模型边界</th><th>本地模型</th></tr></thead><tbody><tr><td>task</td><td>航班任务、航段、航班周期、飞机和恢复数据；供生成与编译使用</td><td><a href="./domain-task/domain-model.html">任务</a>；<code>Application</code> 不注册独立优化模型</td></tr><tr><td>rule</td><td>航段连接、限制、流控制以及可行性/时间/成本计算器</td><td><a href="./domain-rule/domain-model.html">规则</a>；由航班串生成使用的谓词</td></tr><tr><td>crew</td><td>机组成员、等级、排班和转场时间数据</td><td><a href="./domain-crew/domain-model.html">机组</a></td></tr><tr><td>cargo</td><td>货物数据和容量/中断占位模型</td><td><a href="./domain-cargo/domain-model.html">货物</a></td></tr><tr><td>passenger</td><td>旅客数量、取消、舱等/航班变更及其目标和约束管线</td><td><a href="./domain-passenger/domain-model.html">旅客</a></td></tr><tr><td>bunch_generation</td><td>根据任务/规则/机组/货物数据和影子价格生成可行航班串/列</td><td><a href="./domain-bunch_generation/domain-model.html">航班串生成</a>；生成服务，不是独立主问题模型</td></tr><tr><td>bunch_compilation</td><td>主模型列选择、任务/流/机队/航段/容量表达式和增量列</td><td><a href="./domain-bunch_compilation/domain-model.html">航班串编译</a></td></tr><tr><td>bunch_selection</td><td>分支定价策略、约化成本回调和编排</td><td><a href="./domain-bunch_selection/domain-model.html">航班串选择</a>；算法服务，不新增独立变量族</td></tr></tbody></table><h2 id="_3-公共符号与主问题契约" tabindex="-1">3. 公共符号与主问题契约 <a class="header-anchor" href="#_3-公共符号与主问题契约" aria-label="Permalink to &quot;3. 公共符号与主问题契约&quot;">​</a></h2><p>公共符号（<code>B_k</code>、<code>T</code>、<code>A</code>、<code>L</code>）和生成列关联系数在对应上下文页面中定义。编译页是注册 变量、松弛变量、约束和目标的来源；本索引不重复维护这些公式。</p><h2 id="_4-上下文边界与证据" tabindex="-1">4. 上下文边界与证据 <a class="header-anchor" href="#_4-上下文边界与证据" aria-label="Permalink to &quot;4. 上下文边界与证据&quot;">​</a></h2><ol><li><code>BunchGenerationContext.generateFlightTaskBunch</code> 是定价回调：根据影子价格返回生成航班串， 它不是求解器约束。</li><li><code>BunchCompilationContext.register</code> 创建线性元模型符号并返回生效管线。没有被该列表返回的模型类，不是生效断言。</li><li><code>PassengerContext.register</code> 是独立注册路径；只有调用者显式调用它，才能把旅客模型加入编译模型。</li><li><code>BranchAndPriceAlgorithm</code> 负责策略、界、约化成本和生成列的编排，不增加独立领域变量族。</li></ol><p>父页面介绍通用量可执行样例，并提供 Kotlin/Rust 源码入口。上下文级术语和公式可在本索引与拆分页中审阅， 实现行证据见下列源码链接。</p><ol start="5"><li><a href="https://github.com/fuookami/ospf-kotlin/tree/main/ospf-kotlin-example/src/main/fuookami/ospf/kotlin/example/framework_demo/demo4" target="_blank" rel="noreferrer">Kotlin Demo4 源码</a></li><li><a href="https://github.com/fuookami/ospf-rust/tree/main/ospf-rust-example/src/core/demo4.rs" target="_blank" rel="noreferrer">Rust Demo4 源码</a></li></ol>`,14)])])}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
